<?php require_once __DIR__.'/_base.php'; $title='Provider Bookings'; include __DIR__.'/../includes/header.php'; ?><div class="dashboard-shell"><?php include __DIR__.'/../includes/sidebar.php'; ?><section class="content-area"><?php $pid=$pdo->query('SELECT id FROM providers WHERE user_id='.(int)$u['id'])->fetchColumn();if($_SERVER['REQUEST_METHOD']==='POST'){check_csrf();$id=(int)$_POST['booking_id'];$action=post('action');$allowed=['accept'=>'Accepted','reject'=>'Rejected','complete'=>'Completed'];if(isset($allowed[$action])){$new=$allowed[$action];$s=$pdo->prepare("SELECT * FROM bookings WHERE id=? AND provider_id=?");$s->execute([$id,$pid]);if($b=$s->fetch()){if(($action==='accept'&&$b['status']==='Pending')||($action==='reject'&&$b['status']==='Pending')||($action==='complete'&&in_array($b['status'],['Accepted','Confirmed']))){$pdo->prepare('UPDATE bookings SET status=?,updated_at=NOW() WHERE id=?')->execute([$new,$id]);$uid=$b['user_id'];notify($pdo,'Booking '.$new,'Your booking #'.$id.' is now '.$new.'.',$uid,null,'booking');if($new==='Completed')$pdo->prepare('INSERT INTO payments(booking_id,amount,payment_method,payment_status) VALUES(?,?,?,?)')->execute([$id,$b['charges'],'Cash','Pending']);flash('success','Booking updated.');}}}redirect('bookings.php');}$st=$pdo->prepare('SELECT b.*,u.name user_name,s.service_name FROM bookings b JOIN users u ON u.id=b.user_id JOIN services s ON s.id=b.service_id WHERE b.provider_id=? ORDER BY b.booking_date DESC');$st->execute([$pid]);?><h2>Booking Requests</h2><div class="service-card p-3"><div class="table-responsive"><table class="table"><thead><tr><th>ID</th><th>User</th><th>Service</th><th>Date</th><th>Charge</th><th>Status</th><th>Action</th></tr></thead><tbody><?php foreach($st->fetchAll() as $b):?><tr><td>#<?=$b['id']?></td><td><?=e($b['user_name'])?></td><td><?=e($b['service_name'])?></td><td><?=e($b['booking_date'])?> <?=e($b['booking_time'])?></td><td>PKR <?=number_format($b['charges'],2)?></td><td><?=badge($b['status'])?></td><td><?php if($b['status']==='Pending'):?><form method="post" class="d-flex gap-1"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="booking_id" value="<?=$b['id']?>"><button name="action" value="accept" class="btn btn-sm btn-success">Accept</button><button name="action" value="reject" class="btn btn-sm btn-outline-danger">Reject</button></form><?php elseif(in_array($b['status'],['Accepted','Confirmed'])):?><form method="post"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="booking_id" value="<?=$b['id']?>"><button name="action" value="complete" class="btn btn-sm btn-success">Mark Completed</button></form><?php endif;?></td></tr><?php endforeach;?></tbody></table></div></div></section></div><?php include __DIR__.'/../includes/footer.php'; ?>